import{_ as e,o as a,c as l,an as o}from"./chunks/framework.BjfRDIIO.js";const m=JSON.parse('{"title":"Forcing data sets","description":"","frontmatter":{},"headers":[],"relativePath":"manual/forcing_data.md","filePath":"manual/forcing_data.md","lastUpdated":null}'),d={name:"manual/forcing_data.md"};function r(i,t,s,n,c,f){return a(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="Forcing-data-sets" tabindex="-1">Forcing data sets <a class="header-anchor" href="#Forcing-data-sets" aria-label="Permalink to &quot;Forcing data sets {#Forcing-data-sets}&quot;">​</a></h1><p>The weather that drives a run comes from one keyword, <code>weather_source</code>, set to a data-set type of <a href="https://ecojulia.github.io/RasterDataSources.jl/stable" target="_blank" rel="noreferrer">RasterDataSources.jl</a>. Each data set reaches the model as the same hourly forcing, see <a href="./data_sources">One keyword per data set</a>. They differ in coverage, resolution, period, time step and the variables they provide:</p><table tabindex="0"><thead><tr><th style="text-align:left;"><code>weather_source</code></th><th style="text-align:left;">Coverage</th><th style="text-align:left;">Resolution</th><th style="text-align:left;">Period</th><th style="text-align:left;">Time step</th><th style="text-align:left;">Variables</th><th style="text-align:left;">Filled from elsewhere</th><th style="text-align:left;">NicheMapR</th></tr></thead><tbody><tr><td style="text-align:left;"><code>CRUCL2</code></td><td style="text-align:left;">global land</td><td style="text-align:left;">10′ (~18 km)</td><td style="text-align:left;">1961–1990 climatology</td><td style="text-align:left;">monthly means</td><td style="text-align:left;">mean temperature and diurnal range, humidity, wind, rainfall, sunshine, elevation</td><td style="text-align:left;">—</td><td style="text-align:left;"><code>micro_global</code></td></tr><tr><td style="text-align:left;"><code>WorldClim{Climate}</code></td><td style="text-align:left;">global land</td><td style="text-align:left;">30″–10′</td><td style="text-align:left;">1970–2000 climatology</td><td style="text-align:left;">monthly</td><td style="text-align:left;">maximum and minimum temperature, wind, radiation, rainfall, vapour pressure</td><td style="text-align:left;">—</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><code>CHELSA{Climate}</code></td><td style="text-align:left;">global land</td><td style="text-align:left;">30″ (~1 km)</td><td style="text-align:left;">1981–2010 climatology</td><td style="text-align:left;">monthly</td><td style="text-align:left;">maximum and minimum temperature, wind, radiation, rainfall, humidity, cloud</td><td style="text-align:left;">—</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><code>TerraClimate{Historical}</code></td><td style="text-align:left;">global land</td><td style="text-align:left;">1/24° (~4 km)</td><td style="text-align:left;">1958 onwards</td><td style="text-align:left;">monthly</td><td style="text-align:left;">maximum and minimum temperature, wind, vapour pressure deficit, radiation, rainfall, soil moisture</td><td style="text-align:left;">—</td><td style="text-align:left;"><code>micro_terra</code></td></tr><tr><td style="text-align:left;"><code>GRIDMET</code></td><td style="text-align:left;">contiguous USA</td><td style="text-align:left;">1/24° (~4 km)</td><td style="text-align:left;">1979 onwards</td><td style="text-align:left;">daily</td><td style="text-align:left;">maximum and minimum temperature and humidity, wind, radiation, rainfall</td><td style="text-align:left;">—</td><td style="text-align:left;"><code>micro_usa</code></td></tr><tr><td style="text-align:left;"><code>NCEP</code> (surface fluxes)</td><td style="text-align:left;">global</td><td style="text-align:left;">~1.9°</td><td style="text-align:left;">1948 onwards</td><td style="text-align:left;">6-hourly</td><td style="text-align:left;">temperature, wind components, specific humidity, pressure, shortwave and longwave radiation, rainfall</td><td style="text-align:left;">—</td><td style="text-align:left;"><code>micro_ncep</code></td></tr><tr><td style="text-align:left;"><code>ERA5</code></td><td style="text-align:left;">global</td><td style="text-align:left;">0.25° (~30 km)</td><td style="text-align:left;">1940 onwards</td><td style="text-align:left;">hourly</td><td style="text-align:left;">temperature, wind components, dew point, pressure, cloud, shortwave and longwave radiation, rainfall</td><td style="text-align:left;">—</td><td style="text-align:left;"><code>micro_era5</code></td></tr><tr><td style="text-align:left;"><code>ERA5ECMWF</code></td><td style="text-align:left;">global</td><td style="text-align:left;">0.25° (~30 km)</td><td style="text-align:left;">1940 onwards</td><td style="text-align:left;">hourly</td><td style="text-align:left;">as <code>ERA5</code>, from ECMWF&#39;s own store (needs a Copernicus key)</td><td style="text-align:left;">—</td><td style="text-align:left;"><code>micro_era5</code></td></tr><tr><td style="text-align:left;"><code>ERA5ECMWFLand</code></td><td style="text-align:left;">global land</td><td style="text-align:left;">0.1° (~9 km)</td><td style="text-align:left;">1950 onwards</td><td style="text-align:left;">hourly</td><td style="text-align:left;">as <code>ERA5</code> but cloud</td><td style="text-align:left;">cloud from <code>ERA5ECMWF</code></td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><code>AWAP</code></td><td style="text-align:left;">Australia</td><td style="text-align:left;">0.05° (~5 km)</td><td style="text-align:left;">1900 onwards</td><td style="text-align:left;">daily</td><td style="text-align:left;">maximum and minimum temperature, rainfall, radiation, vapour pressure at 09:00 and 15:00</td><td style="text-align:left;">wind from <code>CRUCL2</code></td><td style="text-align:left;"><code>micro_aust</code></td></tr><tr><td style="text-align:left;"><code>SILO</code></td><td style="text-align:left;">Australia</td><td style="text-align:left;">0.05° (~5 km)</td><td style="text-align:left;">1889 onwards</td><td style="text-align:left;">daily</td><td style="text-align:left;">maximum and minimum temperature, rainfall, humidity at the times of the extremes, radiation</td><td style="text-align:left;">wind from <code>CRUCL2</code></td><td style="text-align:left;"><code>micro_silo</code></td></tr><tr><td style="text-align:left;"><code>BARRA</code></td><td style="text-align:left;">Australia</td><td style="text-align:left;">~12 km (R2), ~4 km (C2)</td><td style="text-align:left;">1979 onwards</td><td style="text-align:left;">hourly</td><td style="text-align:left;">temperature, wind, humidity, sea-level pressure, shortwave and longwave radiation, rainfall, elevation</td><td style="text-align:left;">—</td><td style="text-align:left;"><code>micro_barra</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Status, October 2026</p><p>The bindings are being brought in line with new versions of RasterDataSources.jl and Rasters.jl. In the versions used to build this documentation, <code>NCEP</code> and <code>BARRA</code> fail on loading (a layer name and a static elevation layer), and a year of hourly <code>ERA5</code> at a point takes tens of minutes to read from Google&#39;s store (use <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.prefetch_weather!"><code>prefetch_weather!</code></a>, or the faster point route under <a href="/MicroclimateMapper.jl/previews/PR39/manual/forcing_data#Access">Access</a>). <code>CRUCL2</code>, <code>WorldClim</code>, <code>TerraClimate</code> and <code>SILO</code> run in the examples here.</p></div><p>Future climates come in two forms. <code>TerraClimate{Plus2C}</code> and <code>TerraClimate{Plus4C}</code> are TerraClimate&#39;s monthly records with the climate shifted to 2 °C and 4 °C of global warming, with all its variables, and run as TerraClimate does. <code>WorldClim{Future{Climate, …}}</code> and <code>CHELSA{Future{Climate, …}}</code> are climatologies for projected periods under particular climate models and scenarios; they provide only temperature and rainfall, and take their other variables from the matching baseline climatology.</p><h2 id="Choosing-one" tabindex="-1">Choosing one <a class="header-anchor" href="#Choosing-one" aria-label="Permalink to &quot;Choosing one {#Choosing-one}&quot;">​</a></h2><ul><li><p><strong>For a climatology anywhere</strong>, <code>CRUCL2</code> is one small download and runs fastest: one representative day per month. It is the forcing of most examples in this documentation. <code>WorldClim</code> and <code>CHELSA</code> are finer.</p></li><li><p><strong>For future climates</strong>, <code>TerraClimate{Plus2C}</code> or <code>TerraClimate{Plus4C}</code> for warming levels, or the future climatologies of <code>WorldClim</code> and <code>CHELSA</code> for particular climate models and scenarios.</p></li><li><p><strong>For particular years</strong>, <code>TerraClimate</code> is global and monthly. <code>GRIDMET</code> (USA), <code>AWAP</code> and <code>SILO</code> (Australia) are daily and finer.</p></li><li><p><strong>For weather hour by hour</strong>, <code>ERA5</code> or <code>NCEP</code> globally, <code>BARRA</code> for Australia. Hourly forcing carries the timing of fronts, cloud and rain, which daily or monthly forcing can only approximate with a typical diel cycle. The hourly forcing includes the natural covariation among variables which can be important for phenomena like dew and frost; such covariation is stereotyped for the daily and monthly forcing (e.g., lowest wind speed is always at the same time of day).</p></li><li><p><strong>For snow</strong>, daily or hourly forcing. A monthly climatology has no individual storms, so snow cover comes and goes smoothly with the seasons.</p></li></ul><p>Monthly and climatological sources solve 12 representative days, one per month, whatever the dates asked for. Daily and sub-daily sources solve every day, carrying soil and snow state from one day to the next. The second costs about thirty times as much for a year, see <a href="./performance">Performance</a>.</p><h2 id="Access" tabindex="-1">Access <a class="header-anchor" href="#Access" aria-label="Permalink to &quot;Access {#Access}&quot;">​</a></h2><p>Most sources are downloaded once and cached under <code>ENV[&quot;RASTERDATASOURCES_PATH&quot;]</code>, see <a href="./spatial_stack">Built on Rasters and DimensionalData</a>. Some need more:</p><ul><li><p><strong>ERA5</strong> can be reached three ways through RasterDataSources.jl, some still in open pull requests. All need the Zarr extension, <code>using ZarrDatasets</code>, except the last.</p><ul><li><p><code>weather_source = ERA5</code> reads Google&#39;s public ARCO-ERA5 store: no key and nothing downloaded beforehand, but the store is chunked one hour of the whole globe at a time, so a long record at one place is slow.</p></li><li><p><code>weather_source = ERA5ECMWF</code> (or <code>ERA5ECMWFLand</code>, the 9 km land product) reads ECMWF&#39;s own analysis-ready stores, with no queue, given a Copernicus Climate Data Store API key in <code>ENV[&quot;CDS_API_KEY&quot;]</code>. ECMWF calls this access a beta service. For points there is also a copy chunked by place, which is fastest for a long record at one point: the <code>PointQuery</code> loader reads it through PointDataSources.jl, with <code>MicroclimateMapper.loader(::Type{&lt;:ERA5}) = MicroclimateMapper.PointQuery()</code>, see <a href="/MicroclimateMapper.jl/previews/PR39/manual/data_sources#Multiple-dispatch">One keyword per data set</a>.</p></li><li><p><code>ERA5CDS</code> (and <code>ERA5CDSLand</code>) use the Climate Data Store&#39;s own API, which queues a request and downloads regional monthly files, as NicheMapR&#39;s <code>micro_era5</code> does through mcera5. Also keyed. Not yet bound to the model.</p></li></ul></li><li><p><strong><code>SILO</code></strong> asks for an email address, read from <code>ENV[&quot;SILO_EMAIL&quot;]</code>.</p></li><li><p><strong><code>BARRA</code></strong> is read from the THREDDS server of Australia&#39;s National Computational Infrastructure.</p></li><li><p><strong>Point queries.</strong> For a few points, the <code>PointQuery</code> loader fetches time series through <a href="https://github.com/BiophysicalEcology/PointDataSources.jl" target="_blank" rel="noreferrer">PointDataSources.jl</a> instead of grids, see <a href="/MicroclimateMapper.jl/previews/PR39/manual/performance#Point-queries">Performance</a>.</p></li></ul><h2 id="Other-sources" tabindex="-1">Other sources <a class="header-anchor" href="#Other-sources" aria-label="Permalink to &quot;Other sources {#Other-sources}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Keyword</th><th style="text-align:left;">Data sets</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><code>dem_source</code></td><td style="text-align:left;"><code>SRTM</code> (~90 m), <code>CopernicusDEM</code> (30 m), <code>CRUCL2</code>, <code>BARRA</code> (their own elevation grids)</td><td style="text-align:left;">terrain and the elevation correction of the weather, see <a href="./terrain">Terrain and atmosphere</a></td></tr><tr><td style="text-align:left;"><code>soil_moisture_source</code></td><td style="text-align:left;"><code>CPCSoil</code> (monthly climatology, 0.5°)</td><td style="text-align:left;">prescribed soil moisture where the weather source has none, see <a href="./surfaces_soils">Surfaces and soils</a></td></tr><tr><td style="text-align:left;"><code>init_source</code></td><td style="text-align:left;"><code>ERA5</code></td><td style="text-align:left;">initial soil temperature and moisture from one snapshot at the start date</td></tr><tr><td style="text-align:left;"><code>landcover_source</code></td><td style="text-align:left;"><code>EarthEnv{LandCover}</code>, MODIS</td><td style="text-align:left;">albedo and roughness by land-cover class</td></tr></tbody></table>',13)])])}const g=e(d,[["render",r]]);export{m as __pageData,g as default};
